label { font-weight: 600; }
input, button { font: inherit; padding: 10px 14px; border-radius: 6px; }
input { border: 1px solid #8794a3; min-width: 0; }
button { border: 1px solid #2459a6; background: #2459a6; color: white; cursor: pointer; }
button:hover { background: #194783; }
button:disabled { opacity: .6; cursor: wait; }
:focus-visible { outline: 3px solid #da8900; outline-offset: 3px; }
ul { list-style: none; padding: 0; margin-top: 28px; }
li { display: flex; justify-content: space-between; align-items: center; gap: 16px; padding: 16px 0; border-bottom: 1px solid #dce2eb; }
li span { overflow-wrap: anywhere; }
[role="alert"] { color: #a51b26; }
@media (max-width: 600px) {
  main { margin: 16px; padding: 20px; }
  form { align-items: stretch; flex-direction: column; }
}
